import java.util.*;
class Booking {int seats,success;Booking(int n){seats=n;}void book(boolean safe,String user){if(safe){synchronized(this){doBook(user);}}else doBook(user);}private void doBook(String user){if(seats>0){try{Thread.sleep(10);}catch(InterruptedException e){Thread.currentThread().interrupt();}seats--;success++;System.out.println(user+" booked");}else System.out.println(user+" could not book");}}
public class Main {public static void main(String[] args)throws Exception{Scanner sc=new Scanner(System.in);System.out.print("Seats: ");int seats=sc.nextInt();System.out.print("Users: ");int users=sc.nextInt();System.out.print("Synchronization (yes/no): ");boolean safe=sc.next().equalsIgnoreCase("yes");Booking b=new Booking(seats);Thread[] ts=new Thread[users];for(int i=0;i<users;i++){String name="User-"+(i+1);ts[i]=new Thread(()->b.book(safe,name));}for(Thread t:ts)t.start();for(Thread t:ts)t.join();System.out.println("Successful bookings: "+b.success+", seats left: "+b.seats);sc.close();}}
